E("s9f-u4-nucleus-role", 4, ["SC9.10.1"], 1, "var", varset([
  function () { return mcq("Quel énoncé décrit correctement le rôle du noyau d'une cellule?", "Il contient l'information génétique de la cellule et détermine ses processus et ses caractéristiques propres", ["Il contient l'énergie chimique de la cellule et détermine ses processus et ses caractéristiques propres", "Il produit les protéines de la cellule et détermine ses processus et ses caractéristiques propres", "Il protège la cellule des microbes et détermine ses processus et ses caractéristiques propres"], "Le noyau contient l'ADN, qui porte l'information génétique : les instructions qui déterminent les processus cellulaires et les caractères de l'organisme. L'énergie vient des réactions cellulaires et les protéines sont assemblées ailleurs dans la cellule.", {}); }
]), ["Le noyau est le centre d'information de la cellule.", "L'ADN se trouve dans le noyau."]);
E("s9f-u4-traits-heredity", 4, ["SC9.10.1"], 1, "var", varset([
  function () { return mcq("D'où viennent les caractères héréditaires d'un organisme, comme la couleur des yeux chez l'humain?", "De l'information génétique transmise par les cellules reproductrices de ses deux parents à la fécondation", ["Des caractères appris par ses parents à l'école et transmis ensuite à la fécondation des oeufs formés", "Des habitudes acquises par ses parents pendant leur vie et transmises ensuite à la fécondation des oeufs", "De l'alimentation de la mère pendant la grossesse et transmises ensuite à la fécondation des oeufs"], "Les caractères héréditaires sont inscrits dans l'information génétique que les gamètes des deux parents apportent à la fécondation. Les caractères acquis pendant la vie, comme une habitude ou un effet de l'alimentation, ne réécrivent pas cette information et ne se transmettent pas ainsi.", {}); }
]), ["Les caractères héréditaires voyagent dans les cellules reproductrices.", "Un caractère acquis en s'entraînant ne se transmet pas."]);
